import React, { useState } from 'react';

const Contact = () => {
  const [status, setStatus] = useState({ type: '', message: '' });

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus({ type: '', message: '' }); // Reset status

    const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000'; // Use your backend API URL
    const formData = new FormData(e.target); // Gather form data

    try {
      // Make the POST request to the /contact endpoint
      const res = await fetch(`${API_URL}/contact`, {
        method: 'POST',
        body: formData,  // Send form data directly
      });

      const data = await res.json();  // Parse the JSON response from the backend

      // Check if the response is a success
      if (res.ok) {
        setStatus({ type: 'success', message: data.message || 'Message sent successfully!' });
        e.target.reset();  // Reset form on success
      } else {
        setStatus({
          type: 'error',
          message: data.errors ? data.errors.join(', ') : 'Failed to send message.',
        });
      }
    } catch (err) {
      console.error('Submission Error:', err);
      setStatus({ type: 'error', message: 'An error occurred. Please try again.' });
    }
  };

  return (
    <section id="contact">
      <h2>Contact Me</h2>

      {/* Display success or error messages */}
      {status.message && (
        <div
          style={{
            color: status.type === 'success' ? 'green' : 'red',
            marginBottom: '10px',
          }}
        >
          {status.message}
        </div>
      )}

      {/* Contact form */}
      <form onSubmit={handleSubmit}>
        <input type="text" name="name" placeholder="Your Name" required />
        <input type="email" name="email" placeholder="Your Email" required />
        <textarea name="message" placeholder="Your Message" rows="6" required></textarea>
        <button type="submit">Send Message</button>
      </form>
    </section>
  );
};

export default Contact;
